// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {AirDropContract} from "../src/AirDropContract.sol";

contract InvMutTest is Test {
    AirDropContract c;
    function setUp() public { c = new AirDropContract(); }

    function testFuzz_property(address contract_address, address[] memory tos, uint256[] memory vs) public {
        vm.assume(tos.length > 0);
        vm.assume(vs.length > 0);
        vm.assume(tos.length == vs.length);

        bool ok;
        try c.transfer(contract_address, tos, vs) returns (bool r) {
            ok = r;
        } catch {
            ok = false;
        }

        if (contract_address == address(0)) {
            assertTrue(!ok);
        } else {
            assertTrue(ok || !ok);
        }
    }
}
